from collections import Counter

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    for r in range(h - 1):
        for c in range(w):
            color = grid[r][c]
            if color == background:
                continue
            for dc in (-1, 1):
                nc = c + dc
                if not (0 <= nc < w) or grid[r + 1][nc] != color:
                    continue
                rr, cc = r + 2, nc + dc
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == background:
                    out[rr][cc] = color
                    rr += 1
                    cc += dc
    return out

